package com.swarainstitute.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.print.*;
import android.view.*;
import android.webkit.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;

public class MainActivity extends Activity {
    private WebView web,printWeb;
    private SecureStore store;
    private JSONObject root,account;
    private long backgroundAt;
    private String pendingExport,pendingMime,pendingName,restorePassword;
    private static final int EXPORT=100,RESTORE=101;
    private final Object mutex=new Object();
    @Override public void onCreate(Bundle state){super.onCreate(state);store=new SecureStore(this);web=new WebView(this);web.setBackgroundColor(Color.rgb(245,243,248));setContentView(web);
        WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(false);settings.setAllowFileAccess(true);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setBlockNetworkLoads(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSafeBrowsingEnabled(true);settings.setSupportZoom(false);settings.setSaveFormData(false);
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!r.getUrl().toString().startsWith("file:///android_asset/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}});
        web.addJavascriptInterface(new Bridge(),"Android");web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);web.loadUrl("file:///android_asset/index.html");
    }
    private JSONObject require()throws Exception{if(account==null||root==null)throw new IllegalStateException("The app is locked. Please sign in again.");return root.getJSONObject("state");}
    private void owner()throws Exception{require();if(!account.getString("role").equals("Owner"))throw new SecurityException("Only the owner can perform this action.");}
    private String response()throws Exception{return new JSONObject().put("state",Database.view(require(),account.getString("role"),account.optString("entityId"))).put("username",account.getString("username")).put("role",account.getString("role")).put("entityId",account.optString("entityId")).toString();}
    private String error(Exception e){try{return new JSONObject().put("error",e.getMessage()==null?"The operation could not be completed.":e.getMessage()).toString();}catch(Exception ignored){return "{\"error\":\"Operation failed.\"}";}}
    private void js(String function,String text){runOnUiThread(()->web.evaluateJavascript("window."+function+"("+JSONObject.quote(text)+");",null));}
    private void notice(String text){js("nativeNotice",text);}
    private void commit(String action)throws Exception{Database.audit(root.getJSONObject("state"),account.getString("username"),action);store.write(root);}
    private JSONObject studentImport()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open("ramashree-students.json")){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);return new JSONObject(out.toString("UTF-8"));}catch(FileNotFoundException missing){return new JSONObject().put("version",1).put("source","Private student import not included").put("students",new JSONArray());}}
    private JSONObject addRamashreeStudents(JSONObject state)throws Exception{return StudentImport.merge(state,studentImport());}
    private android.content.SharedPreferences prefs(){return getSharedPreferences("security",MODE_PRIVATE);}
    private void failure()throws Exception{int attempts=prefs().getInt("failures",0)+1;prefs().edit().putInt("failures",attempts>=5?0:attempts).putLong("blockedUntil",attempts>=5?System.currentTimeMillis()+60000:0).apply();throw new IllegalArgumentException(attempts>=5?"Too many incorrect PINs. Try again in one minute.":"Username or PIN is incorrect.");}
    private void checkThrottle(){if(System.currentTimeMillis()<prefs().getLong("blockedUntil",0))throw new IllegalStateException("Too many incorrect PINs. Try again in one minute.");}
    private void loggedIn()throws Exception{prefs().edit().putInt("failures",0).putLong("blockedUntil",0).apply();if(prefs().getBoolean("alerts",false))prefs().edit().putString("alertUser",account.getString("username")).apply();}
    private void export(String name,String mime,String contents){pendingName=name;pendingMime=mime;pendingExport=contents;runOnUiThread(()->{try{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(intent,EXPORT);}catch(Exception e){pendingExport=null;notice("No document picker is available on this phone.");}});}
    public class Bridge {
        @JavascriptInterface public boolean isSetup(){return store.exists();}
        @JavascriptInterface public String setup(String institute,String pin){synchronized(mutex){try{if(store.exists())throw new IllegalStateException("Institute already exists. Sign in instead.");JSONObject state=addRamashreeStudents(Database.empty().put("institute",institute.trim()));Database.validate(state);account=SecureStore.account("owner",pin,"Owner","");root=new JSONObject().put("state",state).put("accounts",new JSONArray().put(account));commit("Created institute with Ramashree Gurukul student list");return response();}catch(Exception e){account=null;root=null;return error(e);}}}
        @JavascriptInterface public String clearSamples(){synchronized(mutex){try{owner();JSONObject next=Database.copy(root),data=DemoData.remove(require());JSONArray users=root.getJSONArray("accounts");for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);if(!u.getString("role").equals("Owner"))Database.validateAccount(data,u.getString("role"),u.optString("entityId"));}Database.audit(data,account.getString("username"),"Removed fictional sample records");next.put("state",data);store.write(next);root=next;return response();}catch(Exception e){return error(e);}}}
        @JavascriptInterface public String login(String name,String pin){synchronized(mutex){try{checkThrottle();JSONObject candidate=store.read();JSONArray users=candidate.getJSONArray("accounts");JSONObject found=null;for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);if(u.getString("username").equals(name.toLowerCase(Locale.ROOT).trim()))found=u;}if(found==null||!SecureStore.verify(found,pin)){failure();}root=candidate;account=found;if(account.getString("role").equals("Owner")){if(require().optBoolean("demoData",false)){try{JSONObject cleaned=DemoData.remove(require());Database.audit(cleaned,account.getString("username"),"Removed legacy sample records during version 1.2 upgrade");root.put("state",cleaned);}catch(Exception ignored){}}if(require().optInt("ramashreeStudentImportVersion",0)<studentImport().getInt("version")){JSONObject imported=addRamashreeStudents(require());Database.audit(imported,account.getString("username"),"Imported Ramashree Gurukul student list");root.put("state",imported);store.write(root);}}loggedIn();return response();}catch(Exception e){root=null;account=null;return error(e);}}}
        @JavascriptInterface public String readState(){synchronized(mutex){try{return response();}catch(Exception e){return error(e);}}}
        @JavascriptInterface public String saveState(String text,String action){synchronized(mutex){try{if(text.length()>16*1024*1024)throw new IllegalArgumentException("Institute data is too large.");JSONObject original=require(),merged=Database.merge(original,new JSONObject(text),account.getString("role"),account.optString("entityId"));JSONArray users=root.getJSONArray("accounts");for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);if(!u.getString("role").equals("Owner"))Database.validateAccount(merged,u.getString("role"),u.optString("entityId"));}JSONObject next=Database.copy(root);Database.audit(merged,account.getString("username"),action);next.put("state",merged);store.write(next);root=next;return response();}catch(Exception e){return error(e);}}}
        @JavascriptInterface public void logout(){synchronized(mutex){account=null;root=null;}}
        @JavascriptInterface public void exitApp(){synchronized(mutex){account=null;root=null;}runOnUiThread(()->finishAndRemoveTask());}
        @JavascriptInterface public String listAccounts(){synchronized(mutex){try{owner();JSONArray users=root.getJSONArray("accounts"),out=new JSONArray();for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);out.put(new JSONObject().put("username",u.getString("username")).put("role",u.getString("role")).put("entityId",u.optString("entityId")));}return new JSONObject().put("users",out).toString();}catch(Exception e){return error(e);}}}
        @JavascriptInterface public String addAccount(String name,String pin,String role,String entity){synchronized(mutex){try{owner();Database.validateAccount(require(),role,entity);JSONArray users=root.getJSONArray("accounts");for(int i=0;i<users.length();i++)if(users.getJSONObject(i).getString("username").equals(name.toLowerCase(Locale.ROOT).trim()))throw new IllegalArgumentException("That username is already in use.");users.put(SecureStore.account(name.trim(),pin,role,entity));commit("Created local "+role+" account: "+name);return "{}";}catch(Exception e){return error(e);}}}
        @JavascriptInterface public String removeAccount(String name){synchronized(mutex){try{owner();JSONArray users=root.getJSONArray("accounts"),out=new JSONArray();for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);if(u.getString("username").equals(name)){if(u.getString("role").equals("Owner"))throw new IllegalArgumentException("The owner account cannot be removed.");}else out.put(u);}root.put("accounts",out);commit("Removed local account: "+name);return "{}";}catch(Exception e){return error(e);}}}
        @JavascriptInterface public String changePin(String oldPin,String newPin){synchronized(mutex){try{require();checkThrottle();if(!SecureStore.verify(account,oldPin))failure();JSONObject changed=SecureStore.account(account.getString("username"),newPin,account.getString("role"),account.optString("entityId"));JSONArray users=root.getJSONArray("accounts");for(int i=0;i<users.length();i++)if(users.getJSONObject(i).getString("username").equals(account.getString("username")))users.put(i,changed);account=changed;loggedIn();commit("Changed account PIN");return "{}";}catch(Exception e){return error(e);}}}
        @JavascriptInterface public void exportFile(String name,String mime,String text){synchronized(mutex){try{require();if(!mime.equals("text/csv")||text.length()>16*1024*1024)throw new IllegalArgumentException("Unsupported export.");export(name.replaceAll("[^a-zA-Z0-9._-]","_"),mime,text);}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void shareText(String text){synchronized(mutex){try{require();text=text.trim();if(text.isEmpty())throw new IllegalArgumentException("Enter a reminder message before sharing.");if(text.length()>8000)throw new IllegalArgumentException("Keep the reminder message within 8,000 characters.");String message=text;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,message);startActivity(Intent.createChooser(i,"Send reminder using"));});}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void printReport(String title,String html){synchronized(mutex){try{require();if(html.length()>4*1024*1024)throw new IllegalArgumentException("Report is too large.");runOnUiThread(()->{printWeb=new WebView(MainActivity.this);printWeb.getSettings().setJavaScriptEnabled(false);printWeb.getSettings().setBlockNetworkLoads(true);printWeb.getSettings().setAllowFileAccess(false);printWeb.getSettings().setAllowContentAccess(false);printWeb.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Swara - "+title,view.createPrintDocumentAdapter(title),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}});printWeb.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);});}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void backup(String password){synchronized(mutex){try{owner();String text=SecureStore.backup(root,password);export("Swara-"+LocalDate.now()+".swara-backup","application/json",text);}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void restore(String password){synchronized(mutex){try{owner();if(password.length()<10)throw new IllegalArgumentException("Backup password must have at least 10 characters.");restorePassword=password;runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),RESTORE));}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void enableAlerts(){synchronized(mutex){try{require();prefs().edit().putBoolean("alerts",true).putString("alertUser",account.getString("username")).apply();runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},200);else{ReminderReceiver.schedule(MainActivity.this);notice("Daily local alerts enabled for this account, around 9 am.");}});}catch(Exception e){notice(e.getMessage());}}}
        @JavascriptInterface public void disableAlerts(){synchronized(mutex){try{require();prefs().edit().putBoolean("alerts",false).remove("alertUser").apply();runOnUiThread(()->{PendingIntent p=PendingIntent.getBroadcast(MainActivity.this,0,new Intent(MainActivity.this,ReminderReceiver.class),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null)((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(p);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(1);notice("Local alerts turned off.");});}catch(Exception e){notice(e.getMessage());}}}
    }
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null){pendingExport=null;restorePassword=null;return;}Uri uri=data.getData();if(uri==null)return;
        if(request==EXPORT){String text=pendingExport;pendingExport=null;if(text==null)return;new Thread(()->{try{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Could not open the destination.");out.write(text.getBytes(StandardCharsets.UTF_8));}notice("Export saved.");}catch(Exception e){notice("Export failed: "+e.getMessage());}}).start();}
        if(request==RESTORE){String password=restorePassword;restorePassword=null;if(password==null)return;new Thread(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open this backup.");byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1){out.write(buffer,0,count);if(out.size()>24*1024*1024)throw new IOException("Backup is too large.");}}JSONObject restored=SecureStore.restore(out.toString("UTF-8"),password);synchronized(mutex){owner();Database.audit(restored.getJSONObject("state"),account.getString("username"),"Restored encrypted backup");store.write(restored);root=null;account=null;}js("nativeRestored","");}catch(Exception e){notice("Restore failed. Check the backup password and file. Existing records were kept.");}}).start();}
    }
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==200){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED){ReminderReceiver.schedule(this);notice("Daily local alerts enabled, around 9 am.");}else{prefs().edit().putBoolean("alerts",false).apply();notice("Notifications were not enabled. You can still use Reminders in the app.");}}}
    @Override protected void onPause(){super.onPause();backgroundAt=SystemClock.elapsedRealtime();}
    @Override protected void onResume(){super.onResume();if(backgroundAt>0&&SystemClock.elapsedRealtime()-backgroundAt>120000){synchronized(mutex){account=null;root=null;}js("nativeLocked","");}backgroundAt=0;}
    @Override public void onBackPressed(){web.evaluateJavascript("window.handleBack && window.handleBack()",v->{if(!"true".equals(v))super.onBackPressed();});}
    @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("Android");web.destroy();}if(printWeb!=null)printWeb.destroy();super.onDestroy();}
}
